/* Medic Care Template - Faithful Port */

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000; /* corrected for contrast */
  --vt-accent-ink: #134a99;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink-soft);
  line-height: 1.5;
}

.root,
.root * {
  box-sizing: border-box;
}

/* ─── Navigation ─── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 1.25rem 0;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 1rem;
}

.logo {
  display: inline-block;
}

.brand {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--vt-accent);
  text-decoration: none;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  font-weight: 600;
  font-size: 1rem;
  transition: color 0.3s;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

/* ─── Hero ─── */
.hero {
  padding-top: 0;
}

.heroContainer {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.heroSlider {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
}

.heroTitle {
  font-size: 3rem;
  color: var(--vt-ink);
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.heroDesc {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  font-weight: 300;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  margin-top: 1rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  transition: color 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  text-align: center;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  margin-left: 1.5rem;
  color: var(--vt-ink-soft);
}

/* ─── Sections & Container ─── */
.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* ─── About ─── */
.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2rem;
}

.aboutColText {
  flex: 1;
  min-width: 280px;
}

.aboutTitle {
  color: var(--vt-ink);
  font-size: 2.25rem;
  margin-bottom: 1rem;
}

.aboutText {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  font-weight: 300;
}

.aboutColImage {
  flex: 0 0 350px;
  max-width: 350px;
  text-align: center;
}

.aboutImage {
  width: 100%;
  border-radius: 50%;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

/* ─── Gallery ─── */
.gallery {
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryCol {
  flex: 1 0 50%;
  max-width: 50%;
  padding: 0;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

/* ─── Timeline ─── */
.timelineSection {
  padding-bottom: 0;
}

.timelineTitle {
  text-align: center;
  margin-bottom: 3rem;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  transform: translateX(-50%);
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
}

.timelineNode {
  position: relative;
  display: flex;
  justify-content: flex-end;
  align-items: flex-start;
  margin-bottom: 2rem;
}

.timelineNode:nth-child(even) {
  flex-direction: row-reverse;
}

.timelineDate {
  flex: 1;
  text-align: right;
  padding: 1rem;
}

.timelineNode:nth-child(odd) .timelineDate {
  text-align: left;
}

.timelineIconWrap {
  position: relative;
  z-index: 2;
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 1.5rem;
}

.timelineIcon {
  width: 40px;
  height: 40px;
  background: var(--vt-accent);
  border-radius: 50%;
}

.timelineContent {
  flex: 1;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0 0 0.25rem 0.25rem;
}

.timelineNode:nth-child(odd) .timelineContent {
  text-align: right;
}

.timelineHeading {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  font-size: 1.5rem;
  border-radius: 0.25rem 0.25rem 0 0;
}

.timelineText {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  font-weight: 300;
  font-size: 1rem;
}

/* ─── Contact ─── */
.contactSection {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.contactTitle {
  text-align: center;
  margin-bottom: 2rem;
  color: var(--vt-ink);
}

.contactWrap {
  /* container for FindUs – overrides below ensure child fits */
}

.socialLinks {
  margin-top: 2rem;
  display: flex;
  justify-content: center;
}

/* ─── Footer ─── */
.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerCol {
  flex: 1;
  min-width: 250px;
}

.footerHeading {
  color: var(--vt-ink);
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.hoursText,
.footerText {
  color: var(--vt-ink-soft);
  font-weight: 300;
  font-size: 1rem;
  margin: 0;
  line-height: 1.6;
}

.footerSocial {
  display: flex;
  gap: 1rem;
}

.footerColCopyright {
  flex: 1 0 100%;
  margin-top: 2rem;
  text-align: center;
}

.copyrightText {
  color: var(--vt-ink-soft);
  font-size: 0.875rem;
}

/* ─── Responsive adjustments ─── */
@media screen and (max-width: 991px) {
  .heroContainer {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: auto;
    left: auto;
    width: 100%;
    padding: 2rem;
  }

  .heroSlider {
    height: 400px;
  }

  .aboutColImage {
    flex: 0 0 280px;
    max-width: 280px;
  }

  .timeline::before {
    left: 33px;
  }

  .timelineNode {
    flex-direction: column !important;
    padding-left: 80px;
  }

  .timelineNode:nth-child(even) {
    flex-direction: column !important;
  }

  .timelineDate {
    text-align: left !important;
    order: -1;
  }

  .timelineIconWrap {
    position: absolute;
    left: 0;
    top: 0;
    margin: 0;
  }

  .timelineNode:nth-child(odd) .timelineContent,
  .timelineNode:nth-child(even) .timelineContent {
    text-align: left;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
  }

  .timelineNode {
    padding-left: 70px;
  }

  .timelineIconWrap {
    width: 70px;
    height: 70px;
  }

  .timelineIcon {
    width: 35px;
    height: 35px;
  }

  .navLinks {
    gap: 1rem;
  }

  .footerCol {
    flex: 1 0 100%;
  }
}

/* ─── Global overrides for shared components to prevent overflow ─── */
.root :global(.FindUs_wrap__ChNtH) {
  width: 100%;
  max-width: 100%;
  padding: 0;
  margin: 0;
  box-sizing: border-box;
}

.root :global(.FindUs_mapBox__0e9Qc) {
  width: 100%;
  max-width: 100%;
  margin: 0;
  box-sizing: border-box;
}
